def memo_cycle(definitions, name):
    """
    Compute the value of `name` given a definitions dictionary.
    definitions: dict mapping name -> int or list of dependency names.
    The value of a name defined as a list is the sum of the values of its dependencies.
    Shared dependencies are counted each time they appear.
    Raises ValueError on any reachable cycle or missing dependency.
    """
    memo = {}
    visiting = set()

    def resolve(n):
        if n in memo:
            return memo[n]
        if n in visiting:
            raise ValueError(f"Cycle detected involving {n}")
        if n not in definitions:
            raise ValueError(f"Missing dependency: {n}")
        visiting.add(n)
        try:
            val = definitions[n]
            if isinstance(val, int):
                result = val
            else:  # list
                result = 0
                for dep in val:
                    dep_val = resolve(dep)
                    result += dep_val
            memo[n] = result
            return result
        finally:
            visiting.remove(n)

    return resolve(name)
